fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo (NOT the Ctrl+K search box), open Data Explorer, then the Dashboards section. Create or open a dashboard you own so you can view it. Then walk these toolbar actions IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) dashboard-share-dialog — in the view toolbar (top-right) click the Share button (person-plus / share icon) and confirm a share dialog titled 'Share \"<dashboard name>\"' opens with an 'Add people by name or email...' search box, a 'People with access' section listing the Owner, per-person permission toggles (view/edit/delete/share), and Save/Cancel buttons; close it; (2) dashboard-add-part — enter edit mode (create a new dashboard which opens in edit mode, or click Edit on an owned one), then click the 'Add Part' button (plus icon) in the edit-mode header and confirm an 'Add Panel' / part-picker dialog opens listing selectable part types (or a clear empty state if none are configured); close it; (3) dashboard-open-new-tab — back in view mode, click the 'Open in its own tab' button (up-right-from-square / external-link icon) in the view toolbar and confirm the dashboard opens in its own dedicated Explorer workspace tab (a new tab appears in the tab strip and the dashboard renders without error). Keep going until every action has been visited. You do NOT need to save or fully add anything. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "dashboard-share-dialog",
      "instruction": "open the dashboard Share dialog",
      "visualCriteria": [
        "Clicking Share on an owned dashboard opens a share dialog with a people search input, a 'People with access' section showing the Owner, permission toggle controls (view/edit/delete/share), and Save/Cancel buttons"
      ]
    },
    {
      "name": "dashboard-add-part",
      "instruction": "open Add Part dialog in edit mode",
      "visualCriteria": [
        "In dashboard edit mode, clicking 'Add Part' opens a part/panel picker dialog listing selectable available part types (or a clear empty state if none are configured)"
      ]
    },
    {
      "name": "dashboard-open-new-tab",
      "instruction": "open the dashboard in its own tab",
      "visualCriteria": [
        "Clicking the 'open in its own tab' (external-link icon) button opens the dashboard in a dedicated Explorer tab — a new tab representing the dashboard appears in the tab strip and the dashboard renders without error"
      ]
    }
  ]
}
